function removeSlide(id: string) {
  const slide = slides.find((item) => item.id === id);
  if (!slide) return;
  const meaningful = Boolean(slide.title.trim() || slide.body.trim() || slide.referenceUrl.trim() || slide.anatomyReference || slide.anatomyReferences);
